// Counts the Angular API uses that the guide "Angular features" quotes, so its numbers cannot go
// stale: `node tools/feature-counts.mjs` writes
// `projects/docs/src/app/generated/feature-counts.ts`; `--check` fails when the file is out of
// date (`corepack pnpm lint` runs the check, `corepack pnpm docs:gen` writes the file).
//
// The library counts read `projects/star-ng` without spec files; the docs counts read
// `projects/docs/src` without generated files and without the guide. Each count is the number of matches of a pattern
// in the source text (comments included) and the number of files with a match.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { routesFromNav } from './check-prerender.mjs';

const root = join(fileURLToPath(new URL('.', import.meta.url)), '..');
const output = join(root, 'projects/docs/src/app/generated/feature-counts.ts');

/** The patterns, by key. `lib` counts the library, `docs` the docs application. */
export const PATTERNS = {
  // Declarations (`= input(...)`, `= model<...>(...)`): reads such as `this.model()` do not count.
  input: /=\s*input(<[^=;]*?>)?\(/g,
  inputRequired: /=\s*input\.required\b/g,
  model: /=\s*model(<[^=;]*?>)?\(/g,
  modelRequired: /=\s*model\.required\b/g,
  output: /=\s*output(<[^=;]*?>)?\(/g,
  viewChild: /=\s*viewChild(\.required)?(<[^=;]*?>)?\(/g,
  viewChildren: /=\s*viewChildren(<[^=;]*?>)?\(/g,
  contentChild: /=\s*contentChild(\.required)?(<[^=;]*?>)?\(/g,
  contentChildren: /=\s*contentChildren(<[^=;]*?>)?\(/g,
  signal: /=\s*signal(<[^=;]*?>)?\(/g,
  computed: /=\s*computed(<[^=;]*?>)?\(/g,
  linkedSignal: /=\s*linkedSignal(<[^=;]*?>)?\(/g,
  resource: /=\s*resource(<[^=;]*?>)?\(/g,
  // Calls.
  untracked: /\buntracked\(/g,
  effect: /\beffect\(/g,
  afterRenderEffect: /\bafterRenderEffect\(/g,
  afterNextRender: /\bafterNextRender\(/g,
  afterEveryRender: /\bafterEveryRender\(/g,
  inject: /\binject(<[^=;]*?>)?\(/g,
  takeUntilDestroyed: /\btakeUntilDestroyed\(/g,
  isPlatformBrowser: /\bisPlatformBrowser\(/g,
  toSignal: /\btoSignal\(/g,
  // Names and template syntax.
  formValueControl: /\bFormValueControl\b/g,
  formCheckboxControl: /\bFormCheckboxControl\b/g,
  signalForms: /from '@angular\/forms\/signals'/g,
  if: /@if\b/g,
  for: /@for\b/g,
  switch: /@switch\b/g,
  let: /@let\s/g,
  host: /\bhost: \{/g,
  onPush: /ChangeDetectionStrategy\.OnPush/g,
  destroyRef: /\bDestroyRef\b/g,
  booleanAttribute: /\bbooleanAttribute\b/g,
  numberAttribute: /\bnumberAttribute\b/g,
};

function sourceFiles(folder, skip) {
  return readdirSync(folder, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile() && /\.(ts|html)$/.test(entry.name))
    .map((entry) => join(entry.parentPath, entry.name))
    .filter((file) => !skip(relative(root, file).replaceAll('\\', '/')));
}

/** `{ key: { uses, files } }` for the files. */
export function countIn(files) {
  const texts = files.map((file) => readFileSync(file, 'utf8'));
  const counts = {};
  for (const [key, pattern] of Object.entries(PATTERNS)) {
    let uses = 0;
    let withMatch = 0;
    for (const text of texts) {
      const found = text.match(pattern)?.length ?? 0;
      uses += found;
      if (found) withMatch++;
    }
    counts[key] = { uses, files: withMatch };
  }
  return counts;
}

export function featureCounts() {
  const lib = sourceFiles(join(root, 'projects/star-ng'), (path) => path.endsWith('.spec.ts'));
  const docs = sourceFiles(
    join(root, 'projects/docs/src'),
    // The guide quotes the patterns in its own text, so it does not count itself.
    (path) =>
      path.endsWith('.spec.ts') ||
      path.includes('/generated/') ||
      path.endsWith('/angular-features.guide.ts'),
  );
  const specs = readdirSync(join(root, 'projects/star-ng'), { recursive: true }).filter((path) =>
    String(path).endsWith('.spec.ts'),
  ).length;
  const pages = routesFromNav(
    readFileSync(join(root, 'projects/docs/src/app/nav.ts'), 'utf8'),
  ).length;
  return { lib: countIn(lib), docs: countIn(docs), specFiles: specs, pages };
}

export function render(counts) {
  return (
    '// Generated by tools/feature-counts.mjs: do not edit. Run `corepack pnpm docs:gen`.\n' +
    '// Counts of Angular API uses for the guide "Angular features".\n' +
    `export const FEATURE_COUNTS = ${JSON.stringify(counts, null, 2)} as const;\n`
  );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const text = render(featureCounts());
  if (process.argv.includes('--check')) {
    let current = '';
    try {
      current = readFileSync(output, 'utf8');
    } catch {
      // Missing file: out of date.
    }
    if (current.replace(/\r\n/g, '\n') !== text) {
      console.error(
        'feature-counts: projects/docs/src/app/generated/feature-counts.ts is out of date. Run `corepack pnpm docs:gen`.',
      );
      process.exit(1);
    }
    console.log('feature-counts: up to date');
  } else {
    writeFileSync(output, text);
    console.log(`feature-counts: wrote ${relative(root, output)}`);
  }
}
